/* --- Variables & Reset --- */
:root {
  /* Colors */
  --color-primary: #2D6A4F;
  --color-primary-light: #40916c;
  --color-primary-dark: #1b4332;
  --color-accent: #F4A261;
  --color-accent-hover: #e76f51;
  --color-bg: #FEFAE0;
  --color-bg-alt: #FAEDCD;
  --color-text: #333333;
  --color-text-light: #666666;
  --color-white: #FFFFFF;
  --color-border: rgba(45, 106, 79, 0.15);

  /* Typography */
  --font-heading: 'Poppins', sans-serif;
  --font-body: 'Inter', sans-serif;

  /* Spacing */
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 2rem;
  --spacing-xl: 4rem;

  /* Shadows & Radius */
  --radius-md: 12px;
  --radius-lg: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 4px 6px rgba(0,0,0,0.05);
  --shadow-md: 0 10px 15px rgba(0,0,0,0.08);
  --shadow-lg: 0 20px 25px rgba(0,0,0,0.1);
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-body);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--color-primary-dark);
  line-height: 1.2;
}

a {
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}

ul {
  list-style: none;
}

img, svg {
  max-width: 100%;
  height: auto;
  display: block;
}

/* --- Layout --- */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-lg);
}

.section-spacing {
  padding: var(--spacing-xl) 0;
}

.section-header {
  margin-bottom: var(--spacing-lg);
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
}

.section-header.center {
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.section-header h2 {
  font-size: 2.25rem;
}

.section-subtitle {
  color: var(--color-text-light);
  font-size: 1.125rem;
  margin-top: var(--spacing-sm);
  max-width: 600px;
}

/* --- Buttons & Inputs --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 1.75rem;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  text-align: center;
}

.btn-primary {
  background-color: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background-color: var(--color-primary-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn-secondary:hover {
  background-color: rgba(45, 106, 79, 0.05);
  transform: translateY(-2px);
}

.btn-accent {
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
}

.btn-accent:hover {
  background-color: var(--color-accent-hover);
  color: var(--color-white);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.icon-btn {
  background: transparent;
  border: none;
  color: var(--color-primary);
  font-size: 1.5rem;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
}

.icon-btn:hover {
  background-color: rgba(45, 106, 79, 0.1);
}

.input-group {
  position: relative;
  flex: 1;
}

.input-icon {
  position: absolute;
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-text-light);
  font-size: 1.25rem;
}

input[type="text"],
input[type="email"] {
  width: 100%;
  padding: 1rem 1rem 1rem 3rem;
  border: 2px solid var(--color-border);
  border-radius: var(--radius-full);
  font-family: var(--font-body);
  font-size: 1rem;
  background-color: var(--color-white);
  transition: var(--transition);
  outline: none;
}

input:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(45, 106, 79, 0.2);
}

/* --- Header --- */
.site-header {
  background-color: rgba(254, 250, 224, 0.9);
  backdrop-filter: blur(10px);
  position: sticky;
  top: 0;
  z-index: 100;
  border-bottom: 1px solid var(--color-border);
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 80px;
}

.logo {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--color-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo i {
  color: var(--color-accent);
}

.main-nav ul {
  display: flex;
  gap: 2rem;
}

.main-nav a {
  font-weight: 500;
  color: var(--color-text);
  font-size: 1.05rem;
}

.main-nav a:hover {
  color: var(--color-primary);
}

.header-actions {
  display: flex;
  gap: 0.5rem;
}

/* --- Hero --- */
.hero {
  padding: 4rem 0;
  overflow: hidden;
}

.hero-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.hero-title {
  font-size: 3.5rem;
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--color-text-light);
  margin-bottom: 2.5rem;
}

.hero-cta-group {
  display: flex;
  gap: 1rem;
}

.hero-image-placeholder {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  aspect-ratio: 4/3;
}

/* --- Highlights Banner --- */
.highlights-banner {
  background-color: var(--color-primary);
  color: var(--color-white);
  padding: 3rem 0;
}

.highlights-container {
  display: flex;
  justify-content: space-around;
  flex-wrap: wrap;
  gap: 2rem;
  text-align: center;
}

.highlight-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.highlight-number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-accent);
}

.highlight-label {
  font-size: 1.125rem;
  font-weight: 500;
  margin-top: 0.25rem;
}

/* --- Featured Products Carousel --- */
.carousel-nav {
  display: flex;
  gap: 0.5rem;
}

.carousel-nav .icon-btn {
  background-color: var(--color-white);
  box-shadow: var(--shadow-sm);
}

.carousel-nav .icon-btn:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
}

.carousel-container {
  overflow: hidden;
  padding: 1rem 0; /* space for shadows */
  margin: -1rem 0;
}

.carousel-track {
  display: flex;
  gap: 2rem;
  transition: transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
}

.product-card {
  min-width: 280px;
  background-color: var(--color-white);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
}

.product-image-box {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-md);
  overflow: hidden;
  margin-bottom: 1rem;
  background-color: var(--color-bg-alt);
}

.product-image-box svg {
  width: 100%;
  height: 100%;
}

.product-name {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.product-desc {
  font-size: 0.9rem;
  color: var(--color-text-light);
  margin-bottom: 1rem;
  flex-grow: 1;
}

.product-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
}

.product-price {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1.25rem;
  color: var(--color-primary);
}

.add-to-cart {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: var(--color-bg-alt);
  border: none;
  color: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
}

.add-to-cart:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
}

/* --- Seasonal Picks --- */
.seasonal-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}

.seasonal-card {
  background-color: var(--color-white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  border: 1px solid var(--color-border);
}

.seasonal-card .product-image-box {
  border-radius: 0;
  margin-bottom: 0;
  aspect-ratio: 4/3;
}

.seasonal-info {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

/* --- Categories --- */
.categories-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1.5rem;
  margin-top: 3rem;
}

.category-card {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  aspect-ratio: 1;
  cursor: pointer;
  background-color: var(--color-bg-alt);
  transition: var(--transition);
}

.category-card svg {
  width: 100%;
  height: 100%;
}

.category-overlay {
  position: absolute;
  inset: 0;
  background: rgba(45, 106, 79, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: var(--transition);
}

.category-card:hover {
  transform: scale(1.05);
  box-shadow: var(--shadow-lg);
}

.category-card:hover .category-overlay {
  opacity: 1;
}

.category-title {
  color: var(--color-white);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1.25rem;
  text-align: center;
  padding: 1rem;
  text-shadow: 0 2px 4px rgba(0,0,0,0.3);
  transform: translateY(20px);
  transition: var(--transition);
}

.category-card:hover .category-title {
  transform: translateY(0);
}

/* --- Store Locator --- */
.store-locator-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

.store-locator-content h2 {
  margin-bottom: 1rem;
}

.locator-form {
  display: flex;
  gap: 1rem;
  margin-top: 2rem;
  margin-bottom: 2rem;
}

.store-results {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.store-result-card {
  background-color: var(--color-white);
  padding: 1.5rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
}

.store-result-card h4 {
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
  color: var(--color-primary);
}

.store-result-card p {
  font-size: 0.95rem;
  color: var(--color-text-light);
  margin-bottom: 0.25rem;
}

.store-result-card .distance {
  display: inline-block;
  margin-top: 0.5rem;
  font-weight: 600;
  color: var(--color-accent);
}

.store-locator-map {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  aspect-ratio: 4/3;
  width: 100%;
}

/* --- Newsletter --- */
.newsletter {
  background-color: var(--color-primary-dark);
  color: var(--color-white);
  text-align: center;
}

.newsletter-content {
  max-width: 600px;
  margin: 0 auto;
}

.newsletter h2 {
  color: var(--color-white);
  margin-bottom: 1rem;
}

.newsletter p {
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 2rem;
}

.newsletter-form {
  display: flex;
  gap: 1rem;
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-form input {
  border: none;
}

.newsletter-message {
  margin-top: 1.5rem;
  color: var(--color-accent) !important;
  font-weight: 500;
}

/* --- Footer --- */
.site-footer {
  background-color: var(--color-white);
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--color-border);
}

.footer-container {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 4rem;
}

.footer-brand {
  max-width: 300px;
}

.footer-brand .tagline {
  margin-top: 1rem;
  color: var(--color-text-light);
  font-size: 0.95rem;
}

.footer-links {
  display: flex;
  gap: 4rem;
  flex-wrap: wrap;
}

.footer-column h3 {
  font-size: 1.125rem;
  margin-bottom: 1.5rem;
}

.footer-column ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-column a {
  color: var(--color-text-light);
}

.footer-column a:hover {
  color: var(--color-primary);
}

.social-links {
  display: flex;
  gap: 1rem;
}

.social-links a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background-color: var(--color-bg-alt);
  color: var(--color-primary);
  border-radius: 50%;
  font-size: 1.25rem;
}

.social-links a:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
}

/* --- Responsive --- */
@media (max-width: 992px) {
  .hero-container {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .hero-cta-group {
    justify-content: center;
  }
  .store-locator-container {
    grid-template-columns: 1fr;
  }
  .store-locator-map {
    order: -1;
  }
}

@media (max-width: 768px) {
  .main-nav {
    display: none; /* simple mobile fallback */
  }
  .hero-title {
    font-size: 2.5rem;
  }
  .newsletter-form, .locator-form {
    flex-direction: column;
  }
  .footer-links {
    gap: 2rem;
  }
}

